//! Thumbnails generated by trusted wrapper chrome from anonymous browser image
//! loads. Node-side code handles pixels only and never fetches an avatar URL.
use crate::command::{WsCommand, WsSession};
use crate::data_relocation::ProtectedDirectory;
use async_trait::async_trait;
use base64::{engine::general_purpose::STANDARD, Engine};
use rusqlite::{params, Connection, OpenFlags, OptionalExtension};
use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use std::path::Path;
use std::sync::Arc;
use tokio::sync::Mutex;

const MAX_SIDE: u64 = 128;
const MAX_ROWS: i64 = 128;
const TTL: i64 = 24 * 60 * 60;
// A 128-square RGBA raster plus PNG scanlines, zlib and chunk overhead.
const MAX_PNG: usize = 70 * 1024;
const UNAVAILABLE: &str = "Avatar thumbnail cache unavailable";

type CacheResult<T> = Result<T, Box<dyn std::error::Error + Send + Sync>>;

pub(crate) enum AvatarCommand {
    Get,
    Put,
}

impl AvatarCommand {
    pub(crate) fn is_cache_command(cmd: &str) -> bool {
        matches!(cmd, "avatarCacheGet" | "avatarCachePut")
    }
}

#[async_trait]
impl WsCommand for AvatarCommand {
    fn name(&self) -> &'static str {
        match self {
            Self::Get => "avatarCacheGet",
            Self::Put => "avatarCachePut",
        }
    }

    async fn handle(&self, session: &WsSession, params: &Value) -> Result<Value, String> {
        let state = session.state.clone();
        let size = dimension(params, "size", MAX_SIDE)?;
        let source = source_url(params["url"].as_str().ok_or("Missing avatar URL")?)?;
        let user = state.user.read().await.master_address.clone();
        if session.avatar_user.get_or_init(|| user.clone()) != &user {
            return Err("Avatar cache profile changed; reopen this xite".into());
        }
        let key = cache_key(&user, &source, size);
        let put = match self {
            Self::Get => None,
            Self::Put => {
                let width = dimension(params, "width", size.into())?;
                let len = width as usize * width as usize * 4;
                let rgba = params["rgba"].as_str().ok_or("Missing avatar pixels")?;
                if rgba.len() != len.div_ceil(3) * 4 {
                    return Err("Invalid avatar pixel count".into());
                }
                let pixels = STANDARD.decode(rgba).map_err(|_| "Invalid avatar pixels")?;
                if pixels.len() != len {
                    return Err("Invalid avatar pixel count".into());
                }
                Some((width, pixels))
            }
        };

        let mut storage = state.avatar_cache.0.clone().lock_owned().await;
        tokio::task::spawn_blocking(move || -> CacheResult<Value> {
            if storage.is_none() {
                // The captured state keeps the data-root lease alive even if
                // the requesting socket closes while this task is writing.
                *storage = Some(CacheDb::open(state.data_root.as_deref())?);
            }
            let db = storage.as_mut().expect("initialized above");
            let now = epix_core::now_secs();
            let thumbnail = if let Some((width, pixels)) = put {
                Some(db.put(&key, width, &pixels, now)?)
            } else {
                db.get(&key, now)?
            };
            Ok(json!({"thumbnail": thumbnail.map(|bytes| format!("data:image/png;base64,{}", STANDARD.encode(bytes)))}))
        })
        .await
        .map_err(|_| UNAVAILABLE.to_string())?
        .map_err(|_| UNAVAILABLE.to_string())
    }
}

fn dimension(params: &Value, field: &str, max: u64) -> Result<u32, String> {
    params[field]
        .as_u64()
        .filter(|v| (1..=max).contains(v))
        .map(|v| v as u32)
        .ok_or_else(|| format!("Invalid avatar {field}"))
}

fn source_url(input: &str) -> Result<String, &'static str> {
    const INVALID: &str = "Expected a public HTTP(S) avatar URL";
    if input.len() > 2048
        || input
            .bytes()
            .any(|b| b.is_ascii_control() || b.is_ascii_whitespace())
    {
        return Err(INVALID);
    }
    let mut url = reqwest::Url::parse(input).map_err(|_| INVALID)?;
    let domain = url.domain().ok_or(INVALID)?.trim_end_matches('.');
    if !matches!(url.scheme(), "http" | "https")
        || !url.username().is_empty()
        || url.password().is_some()
        || !domain.contains('.')
        || matches!(
            domain.rsplit('.').next(),
            Some(
                "localhost"
                    | "local"
                    | "epix"
                    | "internal"
                    | "lan"
                    | "home"
                    | "arpa"
                    | "onion"
                    | "i2p"
            )
        )
    {
        return Err(INVALID);
    }
    // Fragments are never transmitted by the processor's HTTP fetch.
    url.set_fragment(None);
    Ok(url.to_string())
}

fn cache_key(user: &str, source: &str, size: u32) -> [u8; 32] {
    let mut hash = Sha256::new();
    // Do not persist a raw profile identifier, image URL, or per-xite history.
    hash.update(b"xid-avatar-v1\0");
    for part in [user.as_bytes(), source.as_bytes()] {
        hash.update((part.len() as u64).to_be_bytes());
        hash.update(part);
    }
    hash.update(size.to_be_bytes());
    hash.finalize().into()
}

#[derive(Default)]
pub(super) struct AvatarCache(Arc<Mutex<Option<CacheDb>>>);

struct CacheDb {
    conn: Connection,
    _directory: Option<ProtectedDirectory>,
}

impl CacheDb {
    fn open(root: Option<&Path>) -> CacheResult<Self> {
        let directory = root
            .map(|root| ProtectedDirectory::open_child(&root.join("private"), "avatar-cache"))
            .transpose()?;
        let conn = match &directory {
            Some(dir) => Connection::open_with_flags(
                dir.path("thumbnails.sqlite3")?,
                OpenFlags::SQLITE_OPEN_READ_WRITE
                    | OpenFlags::SQLITE_OPEN_CREATE
                    | OpenFlags::SQLITE_OPEN_NO_MUTEX
                    | OpenFlags::SQLITE_OPEN_NOFOLLOW,
            )?,
            None => Connection::open_in_memory()?,
        };
        conn.execute_batch(
            "PRAGMA trusted_schema=OFF;
            PRAGMA page_size=4096;
            PRAGMA max_page_count=4096;
            CREATE TABLE IF NOT EXISTS thumbnails (
                key BLOB PRIMARY KEY, created INTEGER NOT NULL, png BLOB NOT NULL
            ) WITHOUT ROWID;",
        )?;
        Ok(Self {
            conn,
            _directory: directory,
        })
    }

    fn get(&self, key: &[u8; 32], now: i64) -> CacheResult<Option<Vec<u8>>> {
        Ok(self
            .conn
            .query_row(
                "SELECT png FROM thumbnails WHERE key=?1 AND created>?2 AND created<=?3
             AND length(png) BETWEEN 1 AND ?4",
                params![key, now - TTL, now, MAX_PNG as i64],
                |row| row.get(0),
            )
            .optional()?)
    }

    fn put(&mut self, key: &[u8; 32], width: u32, pixels: &[u8], now: i64) -> CacheResult<Vec<u8>> {
        // Two xites can finish the same cold load concurrently.
        if let Some(existing) = self.get(key, now)? {
            return Ok(existing);
        }
        let mut png = Vec::new();
        {
            let mut encoder = png::Encoder::new(&mut png, width, width);
            encoder.set_color(png::ColorType::Rgba);
            encoder.set_depth(png::BitDepth::Eight);
            let mut writer = encoder.write_header()?;
            writer.write_image_data(pixels)?;
            writer.finish()?;
        }
        if png.len() > MAX_PNG {
            return Err("Oversize thumbnail".into());
        }
        let tx = self.conn.transaction()?;
        tx.execute(
            "DELETE FROM thumbnails WHERE created<=?1 OR created>?2",
            params![now - TTL, now],
        )?;
        // Make room before insertion. With fixed entry and raster limits the
        // table cannot grow beyond 128 small PNGs across all local identities.
        tx.execute(
            "DELETE FROM thumbnails WHERE key IN (
                    SELECT key FROM thumbnails ORDER BY created DESC, key LIMIT -1 OFFSET ?1)",
            [MAX_ROWS - 1],
        )?;
        tx.execute(
            "INSERT OR REPLACE INTO thumbnails(key,created,png) VALUES (?1,?2,?3)",
            params![key, now, &png],
        )?;
        tx.commit()?;
        Ok(png)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn a_late_fill_cannot_cross_a_profile_switch() {
        use crate::{
            command::{CommandRegistry, WRAPPER_ID_BASE},
            state::AppState,
        };
        let state = AppState::new("test");
        let wrapper = WsSession::new_wrapper(state.clone(), Some("talk.epix".into()));
        let commands = CommandRegistry::with_defaults();
        let key = json!({"url":"https://photos.example.org/avatar.png", "size":80});
        let miss = commands
            .dispatch(&wrapper, "avatarCacheGet", &key, WRAPPER_ID_BASE)
            .await
            .unwrap();
        *state.user.write().await = epix_user::User::generate();
        let put = json!({"url":key["url"], "size":80, "width":1, "rgba":"AAECAw=="});
        assert!(commands
            .dispatch(&wrapper, "avatarCachePut", &put, WRAPPER_ID_BASE)
            .await
            .is_err());
        let next = WsSession::new_wrapper(state, Some("post.epix".into()));
        assert_eq!(
            commands
                .dispatch(&next, "avatarCacheGet", &key, WRAPPER_ID_BASE)
                .await
                .unwrap(),
            miss
        );
    }

    #[test]
    fn private_scope_expiry_and_eviction() {
        let mut cache = CacheDb::open(None).unwrap();
        let source = "https://images.example.org/public.png";
        let alice = cache_key("alice", source, 80);
        let bob = cache_key("bob", source, 80);
        let now = 100_000;
        let sample = [5, 7, 9, 255];
        cache.put(&alice, 1, &sample, now).unwrap();
        assert!(cache.get(&bob, now).unwrap().is_none());
        assert!(cache.get(&alice, now - 1).unwrap().is_none());
        assert!(cache.get(&alice, now + TTL - 1).unwrap().is_some());
        assert!(cache.get(&alice, now + TTL).unwrap().is_none());
        for i in 1..=MAX_ROWS {
            let key = cache_key("alice", &format!("https://images.example.org/{i}"), 80);
            cache.put(&key, 1, &sample, now + i).unwrap();
        }
        assert!(cache.get(&alice, now + MAX_ROWS).unwrap().is_none());
        let count: i64 = cache
            .conn
            .query_row("SELECT count(*) FROM thumbnails", [], |r| r.get(0))
            .unwrap();
        assert_eq!(count, MAX_ROWS);
    }
}
